<x-layouts.app :title="$title" :breadcrumbs="['Beranda','Kesiswaan','Data Siswa',$student->full_name]"><div class="space-y-5"><x-ui.page-header :title="$student->full_name" :description="$student->age_label"><div class="flex gap-2">@can('students.update')<a class="btn btn-primary" href="{{ route('students.edit',$student) }}">Edit</a>@endcan @can('students.change-status')<a class="btn btn-secondary" href="{{ route('students.status.edit',$student) }}">Ubah Status</a>@endcan<a class="btn btn-secondary" href="{{ route('students.index') }}">Kembali</a></div></x-ui.page-header><x-ui.card><div class="grid gap-4 md:grid-cols-2">@foreach(['gender_label'=>'Jenis Kelamin','nisn'=>'NISN','nik'=>'NIK','birth_place'=>'Tempat Lahir','birth_date'=>'Tanggal Lahir','classroom_label'=>'Tingkat/Rombel','status_label'=>'Status','address'=>'Alamat','phone'=>'Nomor Telepon','special_needs'=>'Kebutuhan Khusus','disability'=>'Disabilitas','kip_pip_number'=>'Nomor KIP/PIP','father_name'=>'Nama Ayah','mother_name'=>'Nama Ibu','guardian_name'=>'Nama Wali'] as $key=>$label)<div><p class="text-xs text-slate-500">{{ $label }}</p><p class="font-semibold">@if($key==='birth_date'){{ $student->birth_date?->translatedFormat('d F Y')?:'—' }}@elseif(in_array($key,['nik','address','phone','kip_pip_number'])){{ $display[$key]?:'—' }}@elseif(in_array($key,['special_needs','disability'])){{ $student->$key?:'Tidak Ada' }}@else{{ $student->$key?:'—' }}@endif</p></div>@endforeach</div></x-ui.card><section class="rounded-xl border border-slate-200 bg-white p-4" x-data="rfidWriter()"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="font-bold text-emerald-950">Kartu RFID</h2>@if($student->activeRfidCard)<dl class="mt-2 grid grid-cols-2 gap-x-6 gap-y-1 text-sm"><dt class="text-slate-500">Status</dt><dd class="font-semibold text-emerald-700">Aktif</dd><dt class="text-slate-500">UID</dt><dd>{{ $student->activeRfidCard->maskedUid() }}</dd><dt class="text-slate-500">Diterbitkan</dt><dd>{{ 