ktu penulisan</dt><dd x-text="completedAt"></dd></dl><button type="button" class="btn btn-secondary mt-5" @click="close()">Tutup</button></div></div></section><x-ui.card><div class="grid gap-4 md:grid-cols-2"><div>Dibuat oleh: {{ $student->createdBy?->name?:'—' }}<br>{{ $student->created_at?->translatedFormat('d F Y H:i') }}</div><div>Diperbarui oleh: {{ $student->updatedBy?->name?:'—' }}<br>{{ $student->updated_at?->translatedFormat('d F Y H:i') }}</div></div></x-ui.card></div><script>document.addEventListener('alpine:init',()=>Alpine.data('rfidWriter',()=>({visible:false,waiting:false,status:'',message:'',timer:null,device:'—',completedAt:'—',async open(replace){this.visible=true;this.waiting=true;this.message='Mempersiapkan RFID Writer...';try{const response=await fetch('{{ route('students.rfid-writer.store',$student) }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({replace})});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'RFID Writer tidak terhubung.');this.message='Tempelkan kartu RFID pada reader';this.poll(data.command_id)}catch(error){this.waiting=false;this.status='failed';this.message=error.message}},async poll(id){this.timer=setInterval(async()=>{const response=await fetch(`{{ url('/students/'.$student->id.'/rfid-writer') }}/${id}`,{headers:{Accept:'application/json'}});const data=await response.json();if(['completed','failed','expired'].includes(data.status)){clearInterval(this.timer);this.waiting=false;this.status=data.status;this.device=data.device;this.completedAt=data.completed_at?new Date(data.completed_at).toLocaleString('id-ID'):'—';this.message=data.status==='completed'?'Kartu RFID berhasil ditulis':data.status==='expired'?'Waktu penulisan kartu habis. Silakan coba kembali.':({'CARD_REMOVED':'Kartu dilepas sebelum proses selesai.','VERIFY_FAILED':'Verifikasi data kartu gagal.','DEVICE_ERROR':'RFID Writer tidak terhubung.'}[data.error_code]||'Kartu tidak dapat ditulis.')}}},1500)},close(){clearInterval(this.timer);this.visible=false;if(this.status==='completed')location.reload()}})))</script></x-layouts.app>
